+/**
+ * Lightweight action to update only the tokenCost field of a base model.
+ * Used for inline editing in the admin checkpoints list.
+ */
+const tokenCostUpdateSchema = z.object({
+  tokenCost: z.number().int().min(1).nullable()
+});
+
+export async function updateBaseModelTokenCost(
+  id: string,
+  tokenCost: number | null
+) {
+  const hasPermission = await checkCurrentUserPermission('write-checkpoints');
+  if (!hasPermission) {
+    throw new ForbiddenError(ERROR_IDS.NO_PERMISSION);
+  }
+
+  try {
+    // Validate the tokenCost value
+    const validated = tokenCostUpdateSchema.parse({ tokenCost });
+
+    const result = await prisma.baseModel.update({
+      where: { id },
+      data: { tokenCost: validated.tokenCost }
+    });
+
+    logger.info('Base model token cost updated', {
+      baseModelId: id,
+      tokenCost: validated.tokenCost
+    });
+
+    // Revalidate the admin checkpoints page
+    revalidatePath('/admin/checkpoints');
+
+    return result;
+  } catch (error) {
+    logger.error(
+      'Error updating base model token cost',
+      error instanceof Error ? error : { cause: String(error) }
+    );
+
+    if (error instanceof ForbiddenError || error instanceof z.ZodError) {
+      throw error;
+    }
+
+    throw new DatabaseError('Failed to update base model token cost', {
+      operation: 'updateBaseModelTokenCost',
+      baseModelId: id,
+      error: error instanceof Error ? error.message : String(error)
+    });
+  }
+}
