+/**
+ * Handle new subscription from invoice.payment_succeeded event.
+ * This handles the case where customer.subscription.updated doesn't fire
+ * (e.g., 100% off promo code purchases).
+ */
+const handleNewSubscriptionFromInvoice = async (
+  stripe: Stripe,
+  stripeInvoice: Stripe.Invoice
+) => {
+  const subscriptionId = stripeInvoice.subscription as string;
+  if (!subscriptionId) {
+    logger.error('No subscription ID found in invoice for subscription_create', {
+      invoiceId: stripeInvoice.id
+    });
+    return null;
+  }
+
+  // Fetch the full subscription to get period dates
+  const subscription = await stripe.subscriptions.retrieve(subscriptionId);
+  const stripePlan = subscription.items.data[0].plan as Stripe.Plan;
+
+  const requestedMembership = await getMembershipFromPriceId(stripePlan.id);
+  if (!requestedMembership) {
+    logger.error('Could not determine membership from price ID for new subscription', {
+      priceId: stripePlan.id,
+      subscriptionId
+    });
+    return null;
+  }
+
+  // Find user by stripeCustomerId or email
+  let user = await prisma.user.findFirst({
+    where: {
+      stripeCustomerId: stripeInvoice.customer as string
+    }
+  });
+
+  // If not found by stripeCustomerId, try by email and link the customer
+  if (!user && stripeInvoice.customer_email) {
+    user = await prisma.user.findFirst({
+      where: {
+        email: stripeInvoice.customer_email
+      }
+    });
+
+    if (user) {
+      // Link the Stripe customer ID to the user
+      await prisma.user.update({
+        where: { id: user.id },
+        data: { stripeCustomerId: stripeInvoice.customer as string }
+      });
+    }
+  }
+
+  if (!user) {
+    logger.error('User not found for new subscription invoice', {
+      stripeCustomerId: stripeInvoice.customer,
+      email: stripeInvoice.customer_email,
+      invoiceId: stripeInvoice.id
+    });
+    return null;
+  }
+
+  // Skip if user already has this membership (already processed by subscription.updated)
+  if (user.membership === requestedMembership) {
+    logger.info('User already has the requested membership, skipping', {
+      userId: user.id,
+      membership: requestedMembership
+    });
+    return null;
+  }
+
+  const periodStart = new Date(subscription.current_period_start * 1000);
+  const periodEnd = new Date(subscription.current_period_end * 1000);
+
+  // Check for active trial
+  const activeTrialPeriod = await prisma.trialPeriod.findFirst({
+    where: {
+      userId: user.id,
+      isActive: true
+    }
+  });
+
+  if (activeTrialPeriod) {
+    await deactivateActiveTrialPeriods(user.id, periodStart);
+
+    return await currentTrialSubscriptionPurchased({
+      user,
+      subscriptionId,
+      requestedMembership,
+      periodStart,
+      periodEnd,
+      stripePlan
+    });
+  }
+
+  if (user.membership === Membership.FREE) {
+    return await newUserSubscribed({
+      user,
+      subscriptionId,
+      requestedMembership,
+      periodStart,
+      periodEnd,
+      stripePlan
+    });
+  }
+
+  logger.error('New subscription from invoice not handled by any scenario', {
+    userId: user.id,
+    currentMembership: user.membership,
+    requestedMembership
+  });
+
+  return null;
+};
