@@ -0,0 +1,140 @@
+'use client';
+
+import { useState, useRef, useEffect, useCallback } from 'react';
+import { useTranslations } from 'next-intl';
+import { toast } from 'sonner';
+import { Loader2 } from 'lucide-react';
+
+import { Input } from '@/components/ui/input';
+import { cn } from '@/lib/utils';
+
+interface InlineTokenCostCellProps {
+  baseModelId: string;
+  initialValue: number | null;
+  onSave: (
+    id: string,
+    tokenCost: number | null
+  ) => Promise<{ tokenCost: number | null }>;
+}
+
+export function InlineTokenCostCell({
+  baseModelId,
+  initialValue,
+  onSave
+}: InlineTokenCostCellProps) {
+  const t = useTranslations('admin.checkpoints');
+  const [isEditing, setIsEditing] = useState(false);
+  const [value, setValue] = useState<string>(
+    initialValue?.toString() ?? ''
+  );
+  const [displayValue, setDisplayValue] = useState<number | null>(initialValue);
+  const [isLoading, setIsLoading] = useState(false);
+  const inputRef = useRef<HTMLInputElement>(null);
+
+  // Focus input when entering edit mode
+  useEffect(() => {
+    if (isEditing && inputRef.current) {
+      inputRef.current.focus();
+      inputRef.current.select();
+    }
+  }, [isEditing]);
+
+  const handleSave = useCallback(async () => {
+    // Parse the value
+    const trimmedValue = value.trim();
+    const newValue = trimmedValue === '' ? null : parseInt(trimmedValue, 10);
+
+    // Validate: if not null, must be >= 1
+    if (newValue !== null && (isNaN(newValue) || newValue < 1)) {
+      // Invalid value, don't save
+      setIsEditing(false);
+      setValue(displayValue?.toString() ?? '');
+      return;
+    }
+
+    // Check if value changed
+    if (newValue === displayValue) {
+      setIsEditing(false);
+      return;
+    }
+
+    setIsLoading(true);
+
+    try {
+      const result = await onSave(baseModelId, newValue);
+      setDisplayValue(result.tokenCost);
+      setValue(result.tokenCost?.toString() ?? '');
+      toast.success(t('updateSuccess'));
+    } catch {
+      // Rollback to original value
+      setValue(displayValue?.toString() ?? '');
+      toast.error(t('updateError'));
+    } finally {
+      setIsLoading(false);
+      setIsEditing(false);
+    }
+  }, [value, displayValue, baseModelId, onSave, t]);
+
+  const handleCancel = useCallback(() => {
+    setValue(displayValue?.toString() ?? '');
+    setIsEditing(false);
+  }, [displayValue]);
+
+  const handleKeyDown = useCallback(
+    (e: React.KeyboardEvent) => {
+      if (e.key === 'Enter') {
+        e.preventDefault();
+        handleSave();
+      } else if (e.key === 'Escape') {
+        e.preventDefault();
+        handleCancel();
+      }
+    },
+    [handleSave, handleCancel]
+  );
+
+  const handleBlur = useCallback(() => {
+    // Only save on blur if not already triggered by Enter
+    if (isEditing && !isLoading) {
+      handleSave();
+    }
+  }, [isEditing, isLoading, handleSave]);
+
+  if (isEditing) {
+    return (
+      <div className="flex items-center gap-1">
+        <Input
+          ref={inputRef}
+          type="number"
+          min={1}
+          value={value}
+          onChange={(e) => setValue(e.target.value)}
+          onKeyDown={handleKeyDown}
+          onBlur={handleBlur}
+          disabled={isLoading}
+          className="h-7 w-20 text-sm"
+        />
+        {isLoading && (
+          <Loader2
+            className="h-4 w-4 animate-spin text-muted-foreground"
+            data-testid="loading-spinner"
+          />
+        )}
+      </div>
+    );
+  }
+
+  return (
+    <button
+      type="button"
+      onClick={() => setIsEditing(true)}
+      className={cn(
+        'inline-flex items-center px-2 py-1 rounded text-sm',
+        'hover:bg-muted/50 transition-colors cursor-pointer',
+        'focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1'
+      )}
+    >
+      {displayValue ?? '-'}
+    </button>
+  );
+}
