+
+async function fetchUserSignupStats({
+  startDate,
+  endDate
+}: {
+  startDate?: Date;
+  endDate?: Date;
+}): Promise<UserSignupStats> {
+  const searchParams = new URLSearchParams();
+  if (startDate) searchParams.set('startDate', startDate.toISOString());
+  if (endDate) searchParams.set('endDate', endDate.toISOString());
+
+  const response = await fetch(
+    `/api/admin/user-signup-stats?${searchParams.toString()}`,
+    { method: 'GET' }
+  );
+
+  const payload = (await response.json().catch(() => null)) as
+    | { success: true; data: UserSignupStats }
+    | { success: false; error?: string }
+    | null;
+
+  if (!response.ok || !payload || !payload.success) {
+    throw new Error(
+      payload && 'error' in payload && payload.error
+        ? payload.error
+        : 'Failed to load user signup stats'
+    );
+  }
+
+  return payload.data;
+}
+
+async function fetchUsersSignedUpOnDate(date: string): Promise<UserSignupsByDateResponse> {
+  const searchParams = new URLSearchParams();
+  searchParams.set('date', date);
+  searchParams.set('limit', '200');
+
+  const response = await fetch(`/api/admin/user-signups?${searchParams.toString()}`, {
+    method: 'GET'
+  });
+
+  const payload = (await response.json().catch(() => null)) as
+    | { success: true; data: UserSignupsByDateResponse }
+    | { success: false; error?: string }
+    | null;
+
+  if (!response.ok || !payload || !payload.success) {
+    throw new Error(
+      payload && 'error' in payload && payload.error
+        ? payload.error
+        : 'Failed to load user signups'
+    );
+  }
+
+  return payload.data;
+}
+
+export default function UsersReportClient() {
+  const t = useTranslations();
+  const router = useRouter();
+  const [dateRangeType, setDateRangeType] = useState<DateRangeType>('7days');
+  const [selectedDateRange, setSelectedDateRange] = useState<
+    DateRange | undefined
+  >(undefined);
+  const [selectedDailySignupDate, setSelectedDailySignupDate] = useState<
+    string | null
+  >(null);
+  const [isDailySignupDialogOpen, setIsDailySignupDialogOpen] = useState(false);
+
+  const handleDateRangeTypeChange = (type: DateRangeType) => {
+    setDateRangeType(type);
+    setSelectedDateRange(getDefaultDateRange(type));
+  };
+
+  const dateRange = useMemo(() => {
+    if (selectedDateRange?.from || selectedDateRange?.to) {
+      return selectedDateRange;
+    }
+    return getDefaultDateRange(dateRangeType);
+  }, [selectedDateRange, dateRangeType]);
+
+  const isUsingDefaultRangeValue = useMemo(() => {
+    return isUsingDefaultRange(selectedDateRange, dateRangeType);
+  }, [selectedDateRange, dateRangeType]);
+
+  const previousDateRange = useMemo(() => {
+    if (!isUsingDefaultRangeValue) {
+      return null;
+    }
+    return getPreviousDateRange(dateRangeType);
+  }, [dateRangeType, isUsingDefaultRangeValue]);
+
+  const {
+    data: stats,
+    isLoading,
+    error
+  } = useQuery({
+    queryKey: [
+      'user-signup-stats',
+      dateRangeType,
+      dateRange?.from?.toISOString() ?? null,
+      dateRange?.to?.toISOString() ?? null
+    ],
+    queryFn: async () => {
+      return await fetchUserSignupStats({
+        startDate: dateRange?.from,
+        endDate: dateRange?.to
+      });
+    },
+    enabled: !!(dateRange?.from || dateRange?.to)
+  });
+
+  const { data: previousStats, isLoading: isPreviousLoading } = useQuery({
+    queryKey: [
+      'user-signup-stats',
+      'previous',
+      dateRangeType,
+      previousDateRange?.from?.toISOString() ?? null,
+      previousDateRange?.to?.toISOString() ?? null
+    ],
+    queryFn: async () => {
+      if (!previousDateRange?.from || !previousDateRange?.to) {
+        return null;
+      }
+      return await fetchUserSignupStats({
+        startDate: previousDateRange.from,
+        endDate: previousDateRange.to
+      });
+    },
+    enabled: !!previousDateRange?.from && !!previousDateRange?.to
+  });
+
+  const {
+    data: dailyUsersPayload,
+    isLoading: isDailyUsersLoading,
+    error: dailyUsersError
+  } = useQuery({
+    queryKey: ['user-signups-by-date', selectedDailySignupDate],
+    queryFn: async () => {
