+                  key={`users-report-button-${type}`}
+                  variant={dateRangeType === type ? 'default' : 'outline'}
+                  size="sm"
+                  onClick={() => handleDateRangeTypeChange(type)}
+                >
+                  {t(`admin.users.report.${type}`, {
+                    defaultMessage:
+                      type === 'today'
+                        ? '今日'
+                        : type === 'yesterday'
+                        ? '昨日'
+                        : type === '7days'
+                        ? '7天'
+                        : '30天'
+                  })}
+                </Button>
+              ))}
+            </div>
+            <div className="flex-1 max-w-full md:max-w-[240px]">
+              <DateRangePicker
+                className="w-full flex-col sm:flex-row"
+                date={selectedDateRange || getDefaultDateRange(dateRangeType)}
+                onDateChange={setSelectedDateRange}
+                placeholder={t('common.dateRangePicker.selectDateRange', {
+                  defaultMessage: '選擇日期範圍'
+                })}
