+                              <Link
+                                href={`/admin/users?userIds=${encodeURIComponent(u.id)}`}
+                                className="block min-w-0"
+                                onClick={() => setIsDailySignupDialogOpen(false)}
+                              >
+                                <div className="font-medium truncate">
+                                  {userDisplayName}
+                                </div>
+                                <div className="text-sm text-muted-foreground truncate">
+                                  {userDisplayEmail}
+                                </div>
+                              </Link>
+                            </TableCell>
+                            <TableCell className="text-sm text-muted-foreground">
+                              {signupAt}
+                            </TableCell>
+                            <TableCell className="text-sm">
+                              <div className="font-medium">{invitationCode}</div>
+                              {invitationCodeRedeemedAt &&
+                              invitationCode !== '-' &&
+                              !isSameLocalDay ? (
+                                <div className="text-xs text-muted-foreground">
+                                  {t('admin.users.report.invitationCodeAppliedAt', {
+                                    defaultMessage: '套用時間：{time}',
+                                    time:
+                                      invitationCodeRedeemedAt.toLocaleString('zh-TW')
+                                  })}
+                                </div>
+                              ) : null}
+                            </TableCell>
+                            <TableCell className="text-right">
+                              <ActionDropdownMenu
+                                className="z-[10001]"
+                                actions={[
+                                  {
+                                    label: t('admin.users.report.viewUserInfo', {
+                                      defaultMessage: '查看使用者資訊'
+                                    }),
+                                    onClick: () =>
+                                      openAdminPath(
+                                        `/admin/users?userIds=${encodeURIComponent(u.id)}`,
+                                        { openInNewTab: true }
