@@ -0,0 +1,129 @@
+'use client';
+
+import { TrendingDown, TrendingUp } from 'lucide-react';
+import { useTranslations } from 'next-intl';
+
+import { Card, CardContent } from '@/components/ui/card';
+import { cn } from '@/lib/utils';
+import { calculateChange, calculatePercentage } from '@/utils/stats';
+import type { UserSignupStats } from '@/types/user-signup-stats';
+
+interface AiToolUsageDistributionCardProps {
+  aiToolUsageDistribution: UserSignupStats['aiToolUsageDistribution'];
+  isLoading?: boolean;
+  previousStats?: UserSignupStats | null;
+  isPreviousLoading?: boolean;
+}
+
+export function AiToolUsageDistributionCard({
+  aiToolUsageDistribution,
+  isLoading,
+  previousStats,
+  isPreviousLoading
+}: AiToolUsageDistributionCardProps) {
+  const t = useTranslations();
+
+  const previousAiToolMap = new Map<string, number>();
+  if (previousStats?.aiToolUsageDistribution) {
+    previousStats.aiToolUsageDistribution.forEach((row) => {
+      previousAiToolMap.set(row.aiToolId, row.totalCount);
+    });
+  }
+
+  if (isLoading) {
+    return (
+      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-4 gap-3">
+        {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
+          <Card key={i} className="border shadow-sm">
+            <CardContent className="p-3 flex flex-col items-center text-center">
+              <div className="h-4 w-14 bg-muted rounded mb-2 animate-pulse" />
+              <div className="h-3 w-24 bg-muted rounded mb-2 animate-pulse" />
+              <div className="h-6 w-14 bg-muted rounded mb-1 animate-pulse" />
+              <div className="h-3 w-20 bg-muted rounded animate-pulse" />
+            </CardContent>
+          </Card>
+        ))}
+      </div>
+    );
+  }
+
+  const rows = aiToolUsageDistribution;
+  const totalUsage = rows.reduce((sum, row) => sum + row.totalCount, 0);
+
+  return (
+    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-4 gap-3">
+      {rows.length === 0 ? (
+        <div className="col-span-full">
+          <p className="text-sm text-muted-foreground text-center py-4">
+            {t('admin.users.report.noAiToolUsage', {
+              defaultMessage: '沒有 AI 工具使用數據'
+            })}
+          </p>
+        </div>
+      ) : (
+        rows.map((row, index) => {
+          const previousCount = previousAiToolMap.get(row.aiToolId);
+          const hasChange = previousCount !== undefined && !isPreviousLoading;
+          const change = hasChange
+            ? calculateChange(row.totalCount, previousCount)
+            : null;
+          const isPositive = change !== null && change > 0;
+          const isNegative = change !== null && change < 0;
+          const percentage = calculatePercentage(row.totalCount, totalUsage);
+
+          return (
+            <Card
+              key={row.aiToolId}
+              className="border shadow-sm hover:shadow-md transition-shadow relative"
+            >
+              <div
+                className="absolute top-[-1px] left-[-1px] w-8 h-6 bg-slate-200 z-10 flex items-start justify-start border border-border"
+                style={{ clipPath: 'polygon(0 0, 0 100%, 100% 0)' }}
+              >
+                <span className="text-[10px] font-bold text-muted-foreground leading-none mt-0.5 ml-0.5">
+                  {index + 1}
+                </span>
+              </div>
+
+              <CardContent className="p-3 flex flex-col items-center text-center">
+                <div className="flex items-center gap-1.5 mb-2">
+                  <p className="text-sm font-medium line-clamp-2 break-all">
+                    {row.aiToolName}
+                  </p>
+                  {hasChange && change !== null && (
+                    <div
+                      className={cn(
+                        'flex items-center gap-0.5 text-xs font-medium',
+                        isPositive && 'text-emerald-600 dark:text-emerald-400',
+                        isNegative && 'text-red-600 dark:text-red-400',
+                        !isPositive && !isNegative && 'text-muted-foreground'
+                      )}
+                    >
+                      {isPositive ? (
+                        <TrendingUp className="h-3 w-3" />
+                      ) : isNegative ? (
+                        <TrendingDown className="h-3 w-3" />
+                      ) : null}
+                      <span>
+                        {change > 0 ? '+' : ''}
+                        {change.toFixed(1)}%
+                      </span>
+                    </div>
+                  )}
+                </div>
+
+                <div className="flex items-center gap-1 justify-center">
+                  <p className="text-xl font-bold">
+                    {row.totalCount.toLocaleString()}
+                  </p>
+                  <p className="text-xs text-muted-foreground">({percentage}%)</p>
+                </div>
+              </CardContent>
+            </Card>
+          );
+        })
+      )}
+    </div>
+  );
+}
+
