+'use client';
+
+import {
+  Image as ImageIcon,
+  Sparkles,
+  TrendingDown,
+  TrendingUp,
+  Users,
+  Video
+} from 'lucide-react';
+import { useTranslations } from 'next-intl';
+
+import { Card, CardContent } from '@/components/ui/card';
+import { cn } from '@/lib/utils';
+import { calculateChange } from '@/utils/stats';
+import type { UserSignupStats } from '@/types/user-signup-stats';
+
+interface GenerationAdoptionCardProps {
+  generation: UserSignupStats['generation'];
+  isLoading?: boolean;
+  previousStats?: UserSignupStats | null;
+  isPreviousLoading?: boolean;
+}
+
+export function GenerationAdoptionCard({
+  generation,
+  isLoading,
+  previousStats,
+  isPreviousLoading
+}: GenerationAdoptionCardProps) {
+  const t = useTranslations();
+
+  if (isLoading) {
+    return (
+      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
+        {[1, 2, 3, 4, 5, 6].map((i) => (
+          <Card key={i} className="border shadow-sm">
+            <CardContent className="p-4">
+              <div className="h-3 w-28 bg-muted rounded mb-2 animate-pulse" />
+              <div className="h-8 w-20 bg-muted rounded mb-2 animate-pulse" />
+              <div className="h-3 w-24 bg-muted rounded animate-pulse" />
+            </CardContent>
+          </Card>
+        ))}
+      </div>
+    );
+  }
+
+  const allTime = generation.allTime;
+
+  const previousAllTime = previousStats?.generation.allTime;
+
+  const anyTotal = allTime.imageGeneratedImages + allTime.videoGeneratedOutputs;
+  const previousAnyTotal = previousAllTime
+    ? previousAllTime.imageGeneratedImages + previousAllTime.videoGeneratedOutputs
+    : undefined;
+
+  const userCards = [
+    {
+      key: 'imageUsers',
+      icon: ImageIcon,
+      label: t('admin.users.report.imageGenerationUsers' as never, {
+        defaultMessage: '生成圖片人次'
+      }),
+      users: allTime.usersWithImageGeneration,
+      rate: allTime.rateImage,
+      previousUsers: previousAllTime?.usersWithImageGeneration,
+      previousRate: previousAllTime?.rateImage
+    },
+    {
+      key: 'videoUsers',
+      icon: Video,
+      label: t('admin.users.report.videoGenerationUsers' as never, {
+        defaultMessage: '生成影片人次'
+      }),
+      users: allTime.usersWithVideoGeneration,
+      rate: allTime.rateVideo,
+      previousUsers: previousAllTime?.usersWithVideoGeneration,
+      previousRate: previousAllTime?.rateVideo
+    },
+    {
+      key: 'anyUsers',
+      icon: Sparkles,
+      label: t('admin.users.report.anyGenerationUsers' as never, {
+        defaultMessage: '所有生成人次'
+      }),
+      users: allTime.usersWithAnyGeneration,
+      rate: allTime.rateAny,
+      previousUsers: previousAllTime?.usersWithAnyGeneration,
+      previousRate: previousAllTime?.rateAny
+    }
+  ] as const;
+
+  const totalCards = [
+    {
+      key: 'imageTotal',
+      icon: ImageIcon,
+      label: t('admin.users.report.imageGenerationTotal' as never, {
+        defaultMessage: '生成圖片總數'
+      }),
+      value: allTime.imageGeneratedImages,
+      previousValue: previousAllTime?.imageGeneratedImages
+    },
+    {
+      key: 'videoTotal',
+      icon: Video,
+      label: t('admin.users.report.videoGenerationTotal' as never, {
+        defaultMessage: '生成影片總數'
+      }),
+      value: allTime.videoGeneratedOutputs,
+      previousValue: previousAllTime?.videoGeneratedOutputs
+    },
+    {
+      key: 'anyTotal',
+      icon: Users,
+      label: t('admin.users.report.anyGenerationTotal' as never, {
+        defaultMessage: '所有生成總數'
+      }),
+      value: anyTotal,
+      previousValue: previousAnyTotal
+    }
+  ] as const;
+
+  return (
+    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
+      {userCards.map((card) => {
+        const Icon = card.icon;
+        const hasPrevRate = card.previousRate !== undefined && !isPreviousLoading;
+        const deltaRate = hasPrevRate ? card.rate - Number(card.previousRate) : null;
+        const isPositive = deltaRate !== null && deltaRate > 0;
+        const isNegative = deltaRate !== null && deltaRate < 0;
+
+        return (
+          <Card
+            key={card.key}
+            className="border shadow-sm hover:shadow-md transition-all"
+          >
+            <CardContent className="p-4">
+              <div className="flex items-center justify-center gap-2 mb-2">
+                <Icon className="h-4 w-4 text-muted-foreground" />
+                <p className="text-xs text-muted-foreground text-center">
+                  {t('admin.users.report.generationAllTime', {
+                    defaultMessage: '全部期間'
+                  })}
+                  {' · '}
+                  {card.label}
+                </p>
+              </div>
+
+              <p className="flex items-baseline justify-center gap-2 text-lg md:text-2xl font-bold text-center">
+                <span>{card.users.toLocaleString()}</span>
+                <span className="text-xs md:text-sm font-medium text-muted-foreground">
+                  ({card.rate.toFixed(2)}%)
+                </span>
+              </p>
+
+              <div className="flex items-center justify-center gap-2 mt-1">
+                {hasPrevRate && (
+                  <p className="text-xs text-muted-foreground text-center">
+                    {t('admin.users.report.previousPeriod', {
+                      defaultMessage: '前一期'
+                    })}
+                    : {Number(card.previousRate).toFixed(2)}%
+                  </p>
+                )}
+
+                {deltaRate !== null && hasPrevRate && (
+                  <div
+                    className={cn(
+                      'flex items-center gap-1 text-xs font-medium',
+                      isPositive && 'text-emerald-600 dark:text-emerald-400',
+                      isNegative && 'text-red-600 dark:text-red-400',
+                      !isPositive && !isNegative && 'text-muted-foreground'
+                    )}
+                  >
+                    {isPositive ? (
+                      <TrendingUp className="h-3 w-3" />
+                    ) : isNegative ? (
+                      <TrendingDown className="h-3 w-3" />
+                    ) : null}
+                    <span>
+                      {deltaRate > 0 ? '+' : ''}
+                      {deltaRate.toFixed(2)}%
+                    </span>
+                  </div>
+                )}
+              </div>
+            </CardContent>
+          </Card>
+        );
+      })}
+
+      {totalCards.map((card) => {
+        const Icon = card.icon;
+        const hasPrev = card.previousValue !== undefined && !isPreviousLoading;
+        const change = hasPrev
+          ? calculateChange(card.value, Number(card.previousValue))
+          : null;
+        const isPositive = change !== null && change > 0;
+        const isNegative = change !== null && change < 0;
+
+        return (
+          <Card
+            key={card.key}
+            className="border shadow-sm hover:shadow-md transition-all"
+          >
+            <CardContent className="p-4">
+              <div className="flex items-center justify-center gap-2 mb-2">
+                <Icon className="h-4 w-4 text-muted-foreground" />
+                <p className="text-xs text-muted-foreground text-center">
+                  {t('admin.users.report.generationAllTime', {
+                    defaultMessage: '全部期間'
+                  })}
+                  {' · '}
+                  {card.label}
+                </p>
+              </div>
+
+              <p className="flex items-baseline justify-center gap-2 text-lg md:text-2xl font-bold text-center">
+                <span>{card.value.toLocaleString()}</span>
+              </p>
+
+              <div className="flex items-center justify-center gap-2 mt-1">
+                {hasPrev && (
+                  <p className="text-xs text-muted-foreground text-center">
+                    {t('admin.users.report.previousPeriod', {
+                      defaultMessage: '前一期'
+                    })}
+                    : {Number(card.previousValue).toLocaleString()}
+                  </p>
+                )}
+
+                {change !== null && hasPrev && (
+                  <div
+                    className={cn(
+                      'flex items-center gap-1 text-xs font-medium',
+                      isPositive && 'text-emerald-600 dark:text-emerald-400',
+                      isNegative && 'text-red-600 dark:text-red-400',
+                      !isPositive && !isNegative && 'text-muted-foreground'
+                    )}
+                  >
+                    {isPositive ? (
+                      <TrendingUp className="h-3 w-3" />
+                    ) : isNegative ? (
+                      <TrendingDown className="h-3 w-3" />
+                    ) : null}
+                    <span>
+                      {change > 0 ? '+' : ''}
+                      {change.toFixed(1)}%
+                    </span>
+                  </div>
+                )}
+              </div>
+            </CardContent>
+          </Card>
+        );
+      })}
+    </div>
+  );
+}
+
