+'use client';
+
+import { TrendingDown, TrendingUp } from 'lucide-react';
+import { useTranslations } from 'next-intl';
+
+import { Card, CardContent } from '@/components/ui/card';
+import { cn } from '@/lib/utils';
+import { calculateChange, calculatePercentage } from '@/utils/stats';
+import type { UserSignupStats } from '@/types/user-signup-stats';
+
+interface InvitationCodeStatsCardProps {
+  stats: UserSignupStats;
+  isLoading?: boolean;
+  previousStats?: UserSignupStats | null;
+  isPreviousLoading?: boolean;
+}
+
+export function InvitationCodeStatsCard({
+  stats,
+  isLoading,
+  previousStats,
+  isPreviousLoading
+}: InvitationCodeStatsCardProps) {
+  const t = useTranslations();
+
+  if (isLoading) {
+    return (
+      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-4 gap-3">
+        {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
+          <Card key={i} className="border shadow-sm">
+            <CardContent className="p-3 flex flex-col items-center text-center">
+              <div className="h-4 w-12 bg-muted rounded mb-2 animate-pulse" />
+              <div className="h-3 w-20 bg-muted rounded mb-2 animate-pulse" />
+              <div className="h-6 w-14 bg-muted rounded mb-1 animate-pulse" />
+              <div className="h-3 w-12 bg-muted rounded animate-pulse" />
+            </CardContent>
+          </Card>
+        ))}
+      </div>
+    );
+  }
+
+  const distributionTotal = stats.invitationCode.distribution.reduce(
+    (sum, row) => sum + row.redemptionCount,
+    0
+  );
+
+  const previousDistributionTotal =
+    previousStats?.invitationCode.distribution.reduce(
+      (sum, row) => sum + row.redemptionCount,
+      0
+    ) ?? 0;
+
+  const previousMap = new Map<string, number>(
+    (previousStats?.invitationCode.distribution ?? []).map((row) => [
+      row.invitationCodeId,
+      row.redemptionCount
+    ])
+  );
+
+  const top10 = stats.invitationCode.distribution.slice(0, 10);
+
+  return (
+    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-4 gap-3">
+      {top10.length === 0 ? (
+        <div className="col-span-full">
+          <p className="text-sm text-muted-foreground text-center py-4">
+            {t('admin.users.report.noInvitationCodes', {
+              defaultMessage: '沒有邀請碼數據'
+            })}
+          </p>
+        </div>
+      ) : (
+        top10.map((row, index) => {
+          const pct = calculatePercentage(row.redemptionCount, distributionTotal);
+          const previousCount = previousMap.get(row.invitationCodeId);
+          const hasChange = previousCount !== undefined && !isPreviousLoading;
+          const change = hasChange
+            ? calculateChange(row.redemptionCount, previousCount)
+            : null;
+          const isPositive = change !== null && change > 0;
+          const isNegative = change !== null && change < 0;
+          const previousPct =
+            previousCount === undefined
+              ? null
+              : calculatePercentage(previousCount, previousDistributionTotal);
+
+          return (
+            <Card
+              key={row.invitationCodeId}
+              className="border shadow-sm hover:shadow-md transition-shadow relative"
+            >
+              <div
+                className="absolute top-[-1px] left-[-1px] w-8 h-6 bg-slate-200 z-10 flex items-start justify-start border border-border"
+                style={{ clipPath: 'polygon(0 0, 0 100%, 100% 0)' }}
+              >
+                <span className="text-[10px] font-bold text-muted-foreground leading-none mt-0.5 ml-0.5">
+                  {index + 1}
+                </span>
+              </div>
+
+              <CardContent className="p-3 flex flex-col items-center text-center">
+                <p className="text-sm font-medium line-clamp-2 break-all mb-2">
+                  {row.code}
+                </p>
+
+                <div className="flex items-center gap-1 justify-center">
+                  <p className="text-xl font-bold">
+                    {row.redemptionCount.toLocaleString()}
+                  </p>
+                  <p className="text-xs text-muted-foreground">({pct}%)</p>
+                </div>
+
+                {hasChange && (
+                  <div className="flex items-center justify-center gap-2 mt-1">
+                    <p className="text-[11px] text-muted-foreground text-center">
+                      {t('admin.users.report.previousPeriod', {
+                        defaultMessage: '前一期'
+                      })}
+                      : {previousCount?.toLocaleString()}
+                      {previousPct === null ? '' : ` (${previousPct}%)`}
+                    </p>
+                    {change !== null && (
+                      <div
+                        className={cn(
+                          'flex items-center gap-1 text-[11px] font-medium',
+                          isPositive && 'text-emerald-600 dark:text-emerald-400',
+                          isNegative && 'text-red-600 dark:text-red-400',
+                          !isPositive && !isNegative && 'text-muted-foreground'
+                        )}
+                      >
+                        {isPositive ? (
+                          <TrendingUp className="h-3 w-3" />
+                        ) : isNegative ? (
+                          <TrendingDown className="h-3 w-3" />
+                        ) : null}
+                        <span>
+                          {change > 0 ? '+' : ''}
+                          {change.toFixed(1)}%
+                        </span>
+                      </div>
+                    )}
+                  </div>
+                )}
+              </CardContent>
+            </Card>
+          );
+        })
+      )}
+    </div>
+  );
+}
+
