+      return await fetchUsersSignedUpOnDate(selectedDailySignupDate);
+    },
+    enabled: isDailySignupDialogOpen && !!selectedDailySignupDate
+  });
+
+  const openAdminPath = (path: string, options?: { openInNewTab?: boolean }) => {
